const item = $input.first().json;
const message = item.chatInput || item.message || item.text || item.question || item.body?.message || '';
const raw = String(message || '').trim();
const sessionId = item.sessionId || item.body?.session_id || ('session_' + Date.now());

function generateUuidV4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const requestId = item.requestId || item.body?.request_id || generateUuidV4();

function normalizeText(str) {
  if (!str) return '';
  return str
    .replace(/İ/g, 'i').replace(/I/g, 'i').replace(/ı/g, 'i')
    .replace(/ç/g, 'c').replace(/Ç/g, 'c').replace(/ğ/g, 'g').replace(/Ğ/g, 'g')
    .replace(/ö/g, 'o').replace(/Ö/g, 'o').replace(/ş/g, 's').replace(/Ş/g, 's')
    .replace(/ü/g, 'u').replace(/Ü/g, 'u').replace(/é/g, 'e').replace(/è/g, 'e')
    .replace(/à/g, 'a').replace(/ò/g, 'o').replace(/ù/g, 'u')
    .toLowerCase()
    .replace(/[.,\/#!$%\^&\*;:{}=\-_'~()?'"\+]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function detectLanguage(norm) {
  const trTokens = ['merhaba', 'selam', 'nasilsin', 'tesekkur', 'gorusuruz', 'calisma', 'saatleri', 'izin', 'dogum', 'yillik', 'bugun', 'dun', 'kimler', 'gec', 'kaldi', 'projesinde', 'son', 'durum', 'eposta', 'meyl', 'ozetle', 'bana', 'veritabanini', 'sil', 'neler', 'yapabilirsin', 'yardim', 'kiyafet', 'yemek', 'mesai', 'nedir', 'hangi', 'kisi', 'kac', 'tarif', 'kek', 'fikra'];
  const enTokens = ['hello', 'hi', 'how', 'are', 'you', 'thanks', 'thank', 'goodbye', 'bye', 'good', 'morning', 'working', 'hours', 'leave', 'maternity', 'annual', 'today', 'yesterday', 'who', 'late', 'arrived', 'latest', 'status', 'project', 'email', 'summarize', 'most', 'recent', 'delete', 'database', 'what', 'can', 'help', 'dress', 'code', 'recipe', 'cake', 'joke', 'is', 'available', 'does', 'say', 'give', 'me'];
  const itTokens = ['ciao', 'salve', 'buongiorno', 'buonasera', 'come', 'stai', 'grazie', 'arrivederci', 'orari', 'lavoro', 'ferie', 'permesso', 'congedo', 'maternita', 'oggi', 'ieri', 'chi', 'ritardo', 'arrivato', 'ultimo', 'stato', 'progetto', 'riassumi', 'recente', 'elimina', 'cancella', 'cosa', 'puoi', 'fare', 'aiuto', 'abbigliamento', 'ricetta', 'torta', 'barzelletta', 'previsto', 'dice', 'dammi', 'una', 'qual', 'quali', 'sono'];

  const words = norm.split(/\s+/).filter(Boolean);
  let tr = 0, en = 0, it = 0;
  for (const w of words) {
    if (trTokens.includes(w)) tr += 2;
    if (enTokens.includes(w)) en += 2;
    if (itTokens.includes(w)) it += 2;
  }
  if (norm.includes('how are you') || norm.includes('what is') || norm.includes('working hours') || norm.includes('who arrived') || norm.includes('latest status')) en += 5;
  if (norm.includes('come stai') || norm.includes('orari di lavoro') || norm.includes('chi e arrivato') || norm.includes('ultimo stato')) it += 5;
  if (norm.includes('nasilsin') || norm.includes('calisma saatleri') || norm.includes('kimler gec kaldi') || norm.includes('son durum')) tr += 5;

  // Exclusive token boost
  const excIt = ['ciao','salve','buongiorno','buonasera','arrivederci','grazie','prego','orari','ferie','congedo','maternita','ritardo','riassumi','barzelletta','attivita','aperti','stato'];
  const excEn = ['hello','goodbye','maternity','annual','dress','recipe','cake','joke','summarize','overdue','sprint','blocker'];
  const excTr = ['merhaba','selam','tesekkur','gorusuruz','dogum','yillik','kiyafet','mesai','fikra','yardim','geciken','blokaj'];
  for (const w of words) {
    if (excIt.includes(w)) it += 3;
    if (excEn.includes(w)) en += 3;
    if (excTr.includes(w)) tr += 3;
  }

  if (en > tr && en > it) return { lang: 'en', confidence: 0.98 };
  if (it > tr && it > en) return { lang: 'it', confidence: 0.98 };
  return { lang: 'tr', confidence: tr > 0 ? 0.98 : 0.60 };
}

if (!raw) {
  return [{
    json: {
      is_deterministic: true,
      detected_language: 'tr',
      language_confidence: 1.0,
      response_language: 'tr',
      intent: 'UNKNOWN',
      intent_confidence: 1.0,
      title: 'Açıklama Gerekli',
      answer: 'Lütfen yanıtlayabileceğim bir soru veya mesaj yazınız.',
      confidence: 1.0,
      route_used: 'EMPTY_INPUT',
      retrieval_used: false,
      sources: [],
      raw_message: raw,
      question: raw,
      original_question: raw,
      normalized_question: '',
      session_id: sessionId,
      request_id: requestId
    }
  }];
}

const norm = normalizeText(raw);
const { lang, confidence: langConf } = detectLanguage(norm);

// 1. Security / Malicious Guard in TR, EN, IT
const securityPatterns = [
  'veritabanini sil', 'tablolari sil', 'drop table', 'delete from', 'sifreleri goster', 'credential',
  'delete the database', 'delete database', 'drop database', 'delete from table', 'show passwords', 'ignore previous instructions',
  'elimina il database', 'cancella il database', 'cancella le tabelle', 'mostra le password', 'ignora le istruzioni precedenti'
];
if (securityPatterns.some(p => norm.includes(p))) {
  const secMsgs = {
    tr: 'Bu isteği güvenlik ve yetkilendirme kuralları nedeniyle gerçekleştiremiyorum.',
    en: 'This operation cannot be performed due to security and authorization rules.',
    it: 'Questa operazione non può essere eseguita per motivi di sicurezza e autorizzazione.'
  };
  return [{
    json: {
      is_deterministic: true,
      detected_language: lang,
      language_confidence: langConf,
      response_language: lang,
      intent: 'SECURITY_REJECTED',
      intent_confidence: 1.0,
      title: lang === 'en' ? 'Security Denial' : (lang === 'it' ? 'Rifiuto di Sicurezza' : 'Güvenli Ret'),
      answer: secMsgs[lang] || secMsgs.tr,
      confidence: 1.0,
      route_used: 'SECURITY_GUARD',
      retrieval_used: false,
      sources: [],
      raw_message: raw,
      question: raw,
      original_question: raw,
      normalized_question: norm,
      session_id: sessionId,
      request_id: requestId
    }
  }];
}

// 2. Small Talk in TR, EN, IT
const greetingsTr = ['merhaba', 'merhabalar', 'selam', 'selamlar', 'gunaydin', 'iyi gunler', 'iyi aksamlar', 'hey', 'hi', 'slm'];
const pleasantriesTr = ['nasilsin', 'nasil gidiyor', 'ne haber', 'naber', 'iyi misin'];
const thanksTr = ['tesekkurler', 'tesekkur ederim', 'sag ol', 'sagol', 'eyvallah', 'tamamdir', 'tamam'];
const farewellsTr = ['gorusuruz', 'hosca kal', 'hoscakal', 'bay bay', 'bye'];

const greetingsEn = ['hello', 'hi', 'hey', 'good morning', 'good afternoon', 'good evening'];
const pleasantriesEn = ['how are you', 'how are you doing', 'how is it going', 'whats up'];
const thanksEn = ['thanks', 'thank you', 'thank you very much', 'thx'];
const farewellsEn = ['goodbye', 'bye', 'see you', 'farewell'];

const greetingsIt = ['ciao', 'salve', 'buongiorno', 'buonasera'];
const pleasantriesIt = ['come stai', 'come va', 'come andiamo', 'tutto bene'];
const thanksIt = ['grazie', 'mille grazie', 'molte grazie', 'ti ringrazio'];
const farewellsIt = ['arrivederci', 'a presto', 'addio', 'buona giornata'];

const isSmallTalk = [
  ...greetingsTr, ...pleasantriesTr, ...thanksTr, ...farewellsTr,
  ...greetingsEn, ...pleasantriesEn, ...thanksEn, ...farewellsEn,
  ...greetingsIt, ...pleasantriesIt, ...thanksIt, ...farewellsIt
].includes(norm);

if (isSmallTalk) {
  let ans = '';
  if (lang === 'en') {
    if (pleasantriesEn.includes(norm)) ans = "I'm doing well, thank you. How can I help you?";
    else if (thanksEn.includes(norm)) ans = "You're welcome! Let me know if you need anything else.";
    else if (farewellsEn.includes(norm)) ans = "Goodbye! Have a great day.";
    else ans = "Hello! How can I help you today? You can ask about HR policies, attendance records, or project updates.";
  } else if (lang === 'it') {
    if (pleasantriesIt.includes(norm)) ans = "Sto bene, grazie. Come posso aiutarti?";
    else if (thanksIt.includes(norm)) ans = "Prego! Fammi sapere se posso aiutarti con altro.";
    else if (farewellsIt.includes(norm)) ans = "Arrivederci! Buona giornata.";
    else ans = "Ciao! Come posso aiutarti oggi? Puoi chiedermi informazioni sulle politiche HR, sulle presenze o sugli aggiornamenti di progetto.";
  } else {
    if (pleasantriesTr.includes(norm)) ans = "İyiyim, teşekkür ederim. Size nasıl yardımcı olabilirim?";
    else if (thanksTr.includes(norm)) ans = "Rica ederim. Başka bir konuda yardımcı olabilir miyim?";
    else if (farewellsTr.includes(norm)) ans = "Görüşmek üzere, iyi günler dilerim.";
    else ans = "Merhaba! Size nasıl yardımcı olabilirim? İK politikaları, devam bilgileri veya proje güncellemeleri hakkında soru sorabilirsiniz.";
  }

  return [{
    json: {
      is_deterministic: true,
      detected_language: lang,
      language_confidence: 0.99,
      response_language: lang,
      intent: 'SMALL_TALK',
      intent_confidence: 1.0,
      title: lang === 'en' ? 'Assistant' : (lang === 'it' ? 'Assistente' : 'Asistan'),
      answer: ans,
      confidence: 1.0,
      route_used: 'SMALL_TALK_LOCAL',
      retrieval_used: false,
      sources: [],
      raw_message: raw,
      question: raw,
      original_question: raw,
      normalized_question: norm,
      session_id: sessionId,
      request_id: requestId
    }
  }];
}

// 3. Out-of-Domain Unknown in TR, EN, IT
const unkPatterns = [
  'kek tarifi', 'yemek tarifi', 'fikra anlat', 'sarki soyle', 'sacma bir sey',
  'cake recipe', 'recipe', 'tell me a joke', 'sing a song', 'give me a cake recipe',
  'ricetta per una torta', 'ricetta', 'raccontami una barzelletta', 'dammi una ricetta'
];
if (unkPatterns.some(p => norm.includes(p))) {
  const unkMsgs = {
    tr: 'Bu isteğin hangi bilgi alanıyla ilgili olduğunu netleştiremedim. İK politikası, devam bilgisi veya proje güncellemesi olarak biraz daha açık sorabilir misiniz?',
    en: 'I could not determine which corporate domain this request belongs to. Could you please clarify your question regarding HR policies, attendance data, or project updates?',
    it: "Non sono riuscito a determinare l'ambito aziendale della richiesta. Puoi chiarire la domanda indicando se riguarda le politiche HR, le presenze o gli aggiornamenti di progetto?"
  };
  return [{
    json: {
      is_deterministic: true,
      detected_language: lang,
      language_confidence: langConf,
      response_language: lang,
      intent: 'UNKNOWN',
      intent_confidence: 0.99,
      title: lang === 'en' ? 'Clarification Needed' : (lang === 'it' ? 'Chiarimento Necessario' : 'Açıklama Gerekli'),
      answer: unkMsgs[lang] || unkMsgs.tr,
      confidence: 0.99,
      route_used: 'UNKNOWN',
      retrieval_used: false,
      sources: [],
      raw_message: raw,
      question: raw,
      original_question: raw,
      normalized_question: norm,
      session_id: sessionId,
      request_id: requestId
    }
  }];
}

// 4. Specific domain intents
const attendanceKw = ['gec kaldi', 'geciken', 'gec kalan', 'arrived late', 'who is late', 'who arrived late', 'in ritardo', 'arrivato in ritardo', 'chi e arrivato in ritardo', 'chi e in ritardo'];
const hrKw = ['calisma saatleri', 'calisma saati', 'dogum izni', 'yillik izin', 'kiyafet', 'working hours', 'work hours', 'maternity leave', 'annual leave', 'dress code', 'orari di lavoro', 'congedo di maternita', 'ferie annuali'];
const projectKw = ['temsa', 'vortex', 'eldor obc', 'smart factory', 'latest email', 'son gelen mail', 'riassumi l ultima email', 'latest status', 'son durum', 'ultimo stato'];

const hasAttendance = attendanceKw.some(k => norm.includes(k));
const hasHr = hrKw.some(k => norm.includes(k));
const hasProject = projectKw.some(k => norm.includes(k));

if (hasAttendance) {
  return [{ json: { is_deterministic: true, detected_language: lang, language_confidence: langConf, response_language: lang, intent: 'ATTENDANCE_SQL', intent_confidence: 0.98, question: raw, original_question: raw, normalized_question: norm, session_id: sessionId, request_id: requestId } }];
}
if (hasHr) {
  return [{ json: { is_deterministic: true, detected_language: lang, language_confidence: langConf, response_language: lang, intent: 'HR_POLICY', intent_confidence: 0.98, question: raw, original_question: raw, normalized_question: norm, session_id: sessionId, request_id: requestId } }];
}
if (hasProject) {
  return [{ json: { is_deterministic: true, detected_language: lang, language_confidence: langConf, response_language: lang, intent: 'PROJECT_MAIL', intent_confidence: 0.98, question: raw, original_question: raw, normalized_question: norm, session_id: sessionId, request_id: requestId } }];
}

return [{
  json: {
    is_deterministic: false,
    detected_language: lang,
    language_confidence: langConf,
    response_language: lang,
    intent: 'UNKNOWN',
    question: raw,
    original_question: raw,
    normalized_question: norm,
    raw_message: raw,
    session_id: sessionId,
    request_id: requestId
  }
}];

const guardItem = $('Pre-Router Guard & Normalization').first().json;
const llmRes = $input.first()?.json || {};
const rawText = llmRes.response || '{}';

let parsed = {};
try {
  const jsonMatch = rawText.match(/\{[\s\S]*?\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch (e) {}

let intent = String(parsed.intent || 'UNKNOWN').toUpperCase();
let confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0.0;

const validIntents = ['HR_POLICY', 'ATTENDANCE_SQL', 'COMPANY_KNOWLEDGE', 'PROJECT_MAIL', 'HYBRID', 'SMALL_TALK', 'HELP', 'UNKNOWN', 'SECURITY_REJECTED'];
if (!validIntents.includes(intent)) {
  intent = 'UNKNOWN';
}

if (confidence < 0.75) {
  intent = 'UNKNOWN';
}

let answer = '';
let title = '';
let routeUsed = intent;

if (intent === 'UNKNOWN') {
  title = 'Açıklama Gerekli';
  answer = 'Bu isteğin hangi bilgi alanıyla ilgili olduğunu netleştiremedim. İK politikası, devam bilgisi veya proje güncellemesi olarak biraz daha açık sorabilir misiniz?';
}

return [{
  json: {
    is_deterministic: true,
    intent: intent,
    title: title,
    answer: answer,
    confidence: confidence,
    route_used: routeUsed,
    question: guardItem.question || guardItem.raw_message,
    raw_message: guardItem.raw_message,
    session_id: guardItem.session_id,
    request_id: guardItem.request_id,
    retrieval_used: false,
    sources: []
  }
}];

const item = $input.first().json;
let intent = item.intent;

if (!intent) {
  if (item.route_used === 'CAG_RAG' || item.route_used === 'RAG' || item.route_used === 'CAG' || item.route_used === 'HR_POLICY') {
    intent = 'HR_POLICY';
  } else if (item.route_used === 'ATTENDANCE_SQL' || item.sql || item.generated_sql) {
    intent = 'ATTENDANCE_SQL';
  } else if (item.route_used === 'PROJECT_MAIL' || item.project_code) {
    intent = 'PROJECT_MAIL';
  } else if (item.route_used === 'HYBRID' || item.attendance_evidence || item.mail_evidence) {
    intent = 'HYBRID';
  } else if (item.route_used === 'COMPANY_KNOWLEDGE') {
    intent = 'COMPANY_KNOWLEDGE';
  } else {
    intent = 'UNKNOWN';
  }
}

let title = item.title;
let answer = item.answer || '';
let routeUsed = item.route_used || intent;
let sources = item.sources || [];
let retrievalUsed = !!item.retrieval_used || (sources.length > 0);
let generatedSql = item.sql || item.generated_sql || null;
let isSynthetic = item.is_synthetic || false;
let syntheticNotice = item.synthetic_notice || null;

if (intent === 'SMALL_TALK') {
  const stLang = item.detected_language || item.response_language || 'tr';
  title = stLang === 'en' ? 'Assistant' : (stLang === 'it' ? 'Assistente' : 'Asistan');
  routeUsed = 'SMALL_TALK_LOCAL';
  retrievalUsed = false;
  sources = [];
} else if (intent === 'HELP') {
  title = 'Yardım';
  routeUsed = 'HELP_LOCAL';
  retrievalUsed = false;
  sources = [];
} else if (intent === 'UNKNOWN') {
  title = 'Açıklama Gerekli';
  routeUsed = 'UNKNOWN';
  retrievalUsed = false;
  sources = [];
} else if (intent === 'SECURITY_REJECTED') {
  title = 'Güvenli Ret';
  routeUsed = 'SECURITY_GUARD';
  retrievalUsed = false;
  sources = [];
} else if (intent === 'HR_POLICY') {
  title = 'İK Bilgisi';
  routeUsed = routeUsed || 'HR_POLICY';
} else if (intent === 'ATTENDANCE_SQL') {
  title = 'Devam Bilgisi';
  routeUsed = 'ATTENDANCE_SQL';
} else if (intent === 'COMPANY_KNOWLEDGE') {
  title = 'Şirket Bilgisi';
  routeUsed = 'COMPANY_KNOWLEDGE';
} else if (intent === 'PROJECT_MAIL') {
  title = 'Proje E-postası (RAG)';
  routeUsed = 'PROJECT_MAIL';
} else if (intent === 'HYBRID') {
  title = 'Hibrit Analiz';
  routeUsed = 'HYBRID';
}

function generateUuidV4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

return [{
  json: {
    status: 'SUCCESS',
    intent: intent,
    title: title,
    route_used: routeUsed,
    answer: answer,
    sources: sources,
    source_count: sources.length,
    generated_sql: generatedSql,
    retrieval_used: retrievalUsed,
    is_synthetic: isSynthetic,
    synthetic_notice: syntheticNotice,
    request_id: item.request_id || generateUuidV4(),
    session_id: item.session_id || 'default_session',
    confidence: item.confidence || 0.95
  }
}];
